mapper.update:
UPDATE judgment SET process_status = 'RUNNING', lease_until = #{leaseUntil}
WHERE answer_id = #{answerId}
  AND (process_status IN ('PENDING', 'FAILED')
       OR (process_status = 'RUNNING' AND (lease_until IS NULL OR lease_until < #{now})))

UPDATE judgment
SET process_status = #{judgment.status}, result = #{judgment.result}, held_reason = #{judgment.heldReason,jdbcType=VARCHAR},
    method = #{judgment.by.method}, trial = #{judgment.by.trial},
    model_version = #{judgment.by.model,jdbcType=VARCHAR}, prompt_version = #{judgment.by.prompt,jdbcType=VARCHAR},
    failure_code = NULL, trace_id = #{traceId,jdbcType=VARCHAR}, completed_at = #{now}
WHERE id = #{judgment.id} AND process_status = 'RUNNING' AND lease_until = #{leaseUntil}

UPDATE judgment SET process_status = #{judgment.status}, failure_code = #{judgment.failureCode},
                    retry_count = #{judgment.retryCount}
WHERE id = #{judgment.id} AND process_status = 'RUNNING' AND lease_until = #{leaseUntil}
